// ─── File: CachingPatternsDemo.java ───
// Cache-Aside / Read-Through / Write-Through / Write-Behind, then the
// evolution from per-process (Caffeine) to shared (Redis) when multi-instance.
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class CachingPatternsDemo {
    private static final Logger log = Logger.getLogger("CACHE");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountStore db = new AccountStore();

        // Cache-Aside read: app checks cache, loads DB on miss, populates.
        log.info("=== Cache-Aside (app owns load-on-miss) ===");
        AccountService aside = new AccountService(db, new LocalCache("inst-1"));
        log.info(() -> "read 1 (miss→DB): " + aside.getBalanceCacheAside("SAV2001"));
        log.info(() -> "read 2 (hit):     " + aside.getBalanceCacheAside("SAV2001"));

        // Write-Through: write updates DB + cache together → reads see latest.
        log.info("=== Write-Through (consistent, slower writes) ===");
        aside.updateBalanceWriteThrough("SAV2001", new BigDecimal("950000"));
        log.info(() -> "read after write-through: " + aside.getBalanceCacheAside("SAV2001"));

        // Evolution: TWO instances with PRIVATE in-process caches drift.
        log.info("=== Two instances, PRIVATE Caffeine caches → DRIFT ===");
        AccountService i1 = new AccountService(db, new LocalCache("inst-1"));
        AccountService i2 = new AccountService(db, new LocalCache("inst-2"));
        i1.getBalanceCacheAside("CUR3001");   // inst-1 caches 250000
        i2.getBalanceCacheAside("CUR3001");   // inst-2 caches 250000
        i1.updateBalanceWriteThrough("CUR3001", new BigDecimal("300000")); // only inst-1 cache updated
        log.warning(() -> "inst-2 STALE read: " + i2.getBalanceCacheAside("CUR3001") + " (should be 300000)");

        // Fix: SHARED distributed cache → all instances consistent.
        log.info("=== Two instances, SHARED Redis cache → CONSISTENT ===");
        DistributedCache shared = new DistributedCache();
        AccountService d1 = new AccountService(db, shared);
        AccountService d2 = new AccountService(db, shared);
        d1.getBalanceCacheAside("CUR3001");
        d1.updateBalanceWriteThrough("CUR3001", new BigDecimal("275000")); // shared cache updated
        log.info(() -> "inst-2 FRESH read: " + d2.getBalanceCacheAside("CUR3001") + " (sees 275000)");
    }
}

// ─── store/AccountStore.java (the database) ───
class AccountStore {
    private static final Logger log = Logger.getLogger("CACHE");
    private final Map<String, BigDecimal> rows = new HashMap<>(Map.of(
        "SAV2001", new BigDecimal("1000000"), "CUR3001", new BigDecimal("250000")));
    BigDecimal load(String id) { log.fine(() -> "DB load " + id); return rows.get(id); }
    void save(String id, BigDecimal bal) { log.fine(() -> "DB save " + id + "=" + bal); rows.put(id, bal); }
}

// ─── cache/Cache.java ───
interface Cache {
    BigDecimal get(String key);
    void put(String key, BigDecimal value);
    void evict(String key);
    String name();
}

// ─── cache/LocalCache.java (Caffeine-style, per process — NOT shared) ───
class LocalCache implements Cache {
    private final Map<String, BigDecimal> map = new HashMap<>();
    private final String name;
    LocalCache(String name) { this.name = name; }
    public BigDecimal get(String key) { return map.get(key); }
    public void put(String key, BigDecimal value) { map.put(key, value); }
    public void evict(String key) { map.remove(key); }
    public String name() { return name + " (local Caffeine)"; }
}

// ─── cache/DistributedCache.java (Redis-style, shared across instances) ───
class DistributedCache implements Cache {
    private final Map<String, BigDecimal> shared = new HashMap<>();  // one shared store
    public BigDecimal get(String key) { return shared.get(key); }
    public void put(String key, BigDecimal value) { shared.put(key, value); }
    public void evict(String key) { shared.remove(key); }
    public String name() { return "shared Redis"; }
}

// ─── service/AccountService.java ───
class AccountService {
    private static final Logger log = Logger.getLogger("CACHE");
    private final AccountStore db; private final Cache cache;
    AccountService(AccountStore db, Cache cache) { this.db = db; this.cache = cache; }

    // Cache-Aside: check cache; on miss load DB then populate.
    BigDecimal getBalanceCacheAside(String id) {
        BigDecimal cached = cache.get(id);
        if (cached != null) return cached;         // hit
        BigDecimal fromDb = db.load(id);           // miss → DB
        cache.put(id, fromDb);                     // populate for next time
        return fromDb;
    }
    // Write-Through: write DB + cache together so reads see the latest.
    void updateBalanceWriteThrough(String id, BigDecimal newBal) {
        db.save(id, newBal);
        cache.put(id, newBal);                     // keep cache consistent with DB
        log.info(() -> "write-through " + id + "=" + newBal + " via " + cache.name());
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
